INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(23701, 'Mark 14:72', 'Mark', 14, 72, '&nbsp;بيا چرګ په دوېم ځل بانګ ووئيلو او پطروس ته راياد شُو چې عيسىٰ هغۀ ته فرمائيلى وُو چې، ”د چرګ د دوه ځله بانګ وئيلو نه وړاندې به تۀ زما نه درې ځله اِنکارى شې.“ نو هغه بيا ډېر خفه شو او په ژړا شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23702, 'Mark 15:1', 'Mark', 15, 1, '&nbsp;هر کله چې سحر شو نو مشرانو اِمامانو، د شرعې عالمانو او اولسى مشرانو په صلاح دا فېصله وکړه او عيسىٰ يې وتړلو، بيا يې هغه روان کړو، او پيلاطوس ته يې حواله کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23703, 'Mark 15:2', 'Mark', 15, 2, '&nbsp;پيلاطوس د هغۀ نه تپوس وکړو چې، ”ولې تۀ د يهوديانو بادشاه يې څۀ؟“ هغۀ جواب ورکړو، ”تا په خپله ووې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23704, 'Mark 15:3', 'Mark', 15, 3, '&nbsp;نو بيا مشرانو اِمامانو په هغۀ ډېر اِلزامونه ولګول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23705, 'Mark 15:4', 'Mark', 15, 4, '&nbsp;او پيلاطوس د هغۀ نه بيا تپوس وکړو، ”ولې تا سره د خپلې صفايئ دپاره څۀ جواب نشته څۀ؟ تۀ ګورې چې دوئ په تا څومره اِلزامونه لګوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23706, 'Mark 15:5', 'Mark', 15, 5, '&nbsp;خو پيلاطوس په دې خبره حېران شو چې عيسىٰ بل هيڅ جواب ورنۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23707, 'Mark 15:6', 'Mark', 15, 6, '&nbsp;د اختر په ورځ د ګورنر دا دستور وو چې د خلقو په خوښه به يې يو قېدى آزادولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23708, 'Mark 15:7', 'Mark', 15, 7, '&nbsp;په دغه وخت کښې برابا نومې يو مجرم د باغيانو سره په قېد کښې وو چې د بغاوت په وخت يې قتل کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23709, 'Mark 15:8', 'Mark', 15, 8, '&nbsp;کله چې خلق د دستور په مطابق خواست له راغلل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23710, 'Mark 15:9', 'Mark', 15, 9, '&nbsp;نو پيلاطوس جواب ورکړو چې، ”ولې تاسو دا غواړئ چې زۀ د يهوديانو بادشاه تاسو ته آزاد کړم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23711, 'Mark 15:10', 'Mark', 15, 10, '&nbsp;ځکه چې هغۀ ته پته وه چې مشرانو اِمامانو عيسىٰ د حسد په وجه دۀ ته حواله کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23712, 'Mark 15:11', 'Mark', 15, 11, '&nbsp;خو مشرانو اِمامانو خلق ولمسول چې هغۀ ته ووايئ چې، ”عيسىٰ نه بلکې برابا را آزاد کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23713, 'Mark 15:12', 'Mark', 15, 12, '&nbsp;پيلاطوس بيا هغوئ ته ووئيل چې، ”کوم سړى ته چې تاسو د يهوديانو بادشاه وايئ، د هغۀ سره بيا څۀ وکړم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23714, 'Mark 15:13', 'Mark', 15, 13, '&nbsp;هغوئ چغې کړې، ”دے په سولۍ راځوړند کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23715, 'Mark 15:14', 'Mark', 15, 14, '&nbsp;پيلاطوس تپوس وکړو چې، ”ولې، هغۀ څۀ بد کار کړے دے؟“ خو هغوئ نورې هم چغې تېزې کړې، ”په سولۍ يې کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23716, 'Mark 15:15', 'Mark', 15, 15, '&nbsp;نو پيلاطوس د خلقو د تسلۍ دپاره برابا آزاد کړو او عيسىٰ يې په کوړو ووهلو او په سولۍ کولو ته يې ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23717, 'Mark 15:16', 'Mark', 15, 16, '&nbsp;بيا د ګورنر سپاهيانو عيسىٰ قلعې ته بوتلو او ټوله فوجى دسته يې راجمع کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23718, 'Mark 15:17', 'Mark', 15, 17, '&nbsp;هغوئ عيسىٰ ته کاسنى چُوغه واغوسته او د ازغو تاج يې جوړ کړو او ورته يې په سر کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23719, 'Mark 15:18', 'Mark', 15, 18, '&nbsp;او بيا يې هغۀ ته په دې وينا سره سلامى کوله، ”اے د يهوديانو بادشاه سلامت.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23720, 'Mark 15:19', 'Mark', 15, 19, '&nbsp;او هغوئ هغه په بينت په سر وهلو او توکاڼى يې پرې تُوکل او بيا هغۀ ته په ګوډو شول او د ټوقو سجدې يې ورته وکړلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23721, 'Mark 15:20', 'Mark', 15, 20, '&nbsp;او چې ټوقې يې بس کړې نو کاسنى چُوغه يې ترې وويستله او خپلې جامې يې ورواغوستلې. بيا يې هغه بهر په سولۍ کولو له بوتلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23722, 'Mark 15:21', 'Mark', 15, 21, '&nbsp;د سکندر او د روفوس پلار شمعون څوک چې د کرينى اوسېدونکے وو هغه د کلى نه په هغه لاره راروان وو نو هغوئ هغه په بيګار ونيولو چې د عيسىٰ سولۍ يوسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23723, 'Mark 15:22', 'Mark', 15, 22, '&nbsp;هغوئ عيسىٰ ګولګتا نومې ځائ ته راوستو چې مطلب يې د کوپړو ځائ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23724, 'Mark 15:23', 'Mark', 15, 23, '&nbsp;هغۀ ته يې د مُر چيړ سره ګډ کړى مے ورکول خو هغۀ ونۀ څښل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23725, 'Mark 15:24', 'Mark', 15, 24, '&nbsp;بيا هغوئ هغه په سولۍ وخېژولو او هر يو د خپل حق معلومولو دپاره د هغۀ په جامو پچه واچوله او په خپلو کښې يې تقسيم کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23726, 'Mark 15:25', 'Mark', 15, 25, '&nbsp;د سولۍ کولو وخت د سحر نهۀ بجې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23727, 'Mark 15:26', 'Mark', 15, 26, '&nbsp;او د هغۀ خلاف د اِلزام په تخته څۀ داسې ليکلے وو، ”د يهوديانو بادشاه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23728, 'Mark 15:29', 'Mark', 15, 29, '&nbsp;څوک چې په لاره تېرېدل نو هغۀ پورې يې مسخرې کولې او سرونه به يې خوځول او چغې سورې به يې وهلې، ”اوس خپل ځان ته وګوره، تۀ به د خُدائ دا کور ورانوې او بيا به يې په درېو ورځو کښې جوړوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23729, 'Mark 15:30', 'Mark', 15, 30, '&nbsp;ښه نو بيا خپل ځان بچ کړه، او د دې سولۍ نه راکوز شه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23730, 'Mark 15:31', 'Mark', 15, 31, '&nbsp;دغه شان مشرانو اِمامانو او د شرعې عالمانو هم په خپلو کښې ورپورې مسخرې کولې، او وئيل يې چې، ”هغۀ خو نور خلق بچ کول خو خپل ځان نۀ شى بچ کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23731, 'Mark 15:32', 'Mark', 15, 32, '&nbsp;پرېږدئ چې مسيح، دا د بنى اِسرائيلو بادشاه، دې اوس د سولۍ نه راکوز شى، چې مونږ دا ووينو او ايمان پرې راوړو.“ تر دې چې د دۀ سره په سولۍ شوو مجرمانو هم دۀ ته سپکې سپورې وئيلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23732, 'Mark 15:33', 'Mark', 15, 33, '&nbsp;د غرمې په وخت په ټوله زمکه تيارۀ راخوره شوه او د تېر ماسپښين تر درېو بجو پورې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23733, 'Mark 15:34', 'Mark', 15, 34, '&nbsp;او درې بجې عيسىٰ په زوره چغې کړې چې، ”ايلى، ايلى، لما شبقتنى؟“ چې ترجمه يې دا ده، ”اے زما خُدايه پاکه، اے زما خُدايه، زۀ دې ولې پرېښودلم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23734, 'Mark 15:35', 'Mark', 15, 35, '&nbsp;ځينې ولاړو خلقو چې دا واورېدل نو وې وئيل چې، ”وګورئ، دے اوس الياس ته نعرې وهى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23735, 'Mark 15:36', 'Mark', 15, 36, '&nbsp;نو بيا يو کس ورمنډه کړه، يو اسفنج يې د سرکې نه ډک کړو او د هغۀ شونډو ته يې د يوې چوکې په سر ونيولو چې وې څښې او هغۀ ووئيل، ”اوس به وګورو چې الياس راشى او دے راکوز کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23736, 'Mark 15:37', 'Mark', 15, 37, '&nbsp;بيا عيسىٰ يوه تېزه کريکه وويسته او ساه يې ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23737, 'Mark 15:38', 'Mark', 15, 38, '&nbsp;او د خُدائ د کور پړده د سر نه تر بېخه پورې په مينځ دوه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23738, 'Mark 15:39', 'Mark', 15, 39, '&nbsp;او کوم صوبه دار چې هغۀ ته مخامخ ولاړ وو نو چې هغۀ وليدل چې هغۀ څنګه ساه ورکړه نو وې وئيل، ”بې‌شکه چې دا سړے د خُدائ پاک زوئ وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23739, 'Mark 15:40', 'Mark', 15, 40, '&nbsp;يو څو ښځې هم هلته موجود وې چې د لرې نه يې تماشه کوله. په هغوئ کښې مريم مګدلينى، د کشر يعقوب چې يوسيس مور مريم چې سلومى وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23740, 'Mark 15:41', 'Mark', 15, 41, '&nbsp;نو کله چې عيسىٰ په ګليل کښې وو نو هم دې ښځو د هغۀ تابعدارى کړې وه او د هغۀ خِدمت يې کړے وو او په دوئ کښې نورې ښځې هم وې څوک چې د هغۀ سره يروشلم ته راغلې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23741, 'Mark 15:42', 'Mark', 15, 42, '&nbsp;دا هر څۀ د جمعې په ورځ وشُو، يعنې د تيارۍ په ورځ، د سبت نه يوه ورځ وړاندې. نو چې ماښام رانزدې شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23742, 'Mark 15:43', 'Mark', 15, 43, '&nbsp;د ارمتيه يوسف نومې يو سړے راغلو څوک چې د جرګې يو عزتمند کس وو او هغه په خپله ډېر اُميد سره د خُدائ پاک د بادشاهۍ د راتلو په اِنتظار وو، نو په زړۀ ورتيا سره پيلاطوس له ورغلو او د عيسىٰ لاش يې ترې وغوښتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23743, 'Mark 15:44', 'Mark', 15, 44, '&nbsp;پيلاطوس حېران شو چې هغه مړ شوے هم دے، نو هغۀ صوبه دار راوغوښتو او تپوس يې ترې وکړو چې، ”هغه مړ دے او کۀ نه؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23744, 'Mark 15:45', 'Mark', 15, 45, '&nbsp;کله چې هغه د صوبه دار نه خبر شو چې هغه مړ دے نو هغۀ يوسف له اجازت ورکړو چې لاش يې يوسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23745, 'Mark 15:46', 'Mark', 15, 46, '&nbsp;بيا يوسف د کتان کپړه په بيعه واخسته او د هغۀ لاش يې د سولۍ نه راکوز کړو او کفن يې کړو او په کنستلے شوى قبر کښې يې کېښودو. او يو لوئ کاڼے يې د قبر خولې ته راورغړولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23746, 'Mark 15:47', 'Mark', 15, 47, '&nbsp;او مريم مګدلينى او د يوسيس مور مريم هغه ځائ وليدو په کوم ځائ کښې چې يې هغه کېښودو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23747, 'Mark 16:1', 'Mark', 16, 1, '&nbsp;هر کله چې د سبت ورځ تېره شوه، مريم مګدلينى، د يعقوب مور مريم او سلومى خوشبوداره تېل واخستل او نيت يې وکړو چې ورشى او د عيسىٰ په لاش يې واچوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23748, 'Mark 16:2', 'Mark', 16, 2, '&nbsp;او د اِتوار په ورځ سحر وختى د نمر راختو نه لږ وروستو هغوئ قبر له ورغلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23749, 'Mark 16:3', 'Mark', 16, 3, '&nbsp;په لاره هغوئ يو بل ته ووئيل چې، ”مونږ ته به د غار د خولې نه کاڼے څوک ورغړوى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23750, 'Mark 16:4', 'Mark', 16, 4, '&nbsp;خو چې هغوئ په غور سره وکتل نو څۀ ګورى چې کاڼے د مخکښې نه رغړېدلے وو اګر چې دغه کاڼے ډېر غټ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23751, 'Mark 16:5', 'Mark', 16, 5, '&nbsp;هغوئ چې قبر ته ورننوتلې، نو يو ځوان يې وليدو چې ښى اړخ ته ناست وو او سپينه چُوغه يې اچولې وه، او هغوئ اريانې دريانې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23752, 'Mark 16:6', 'Mark', 16, 6, '&nbsp;خو فرښتې هغوئ ته وفرمائيل، ”مۀ يرېږئ، تاسو د عيسىٰ ناصرى ليدو له راغلى يئ څوک چې په سولۍ کړے شوے وو. هغه بيا پورته کړے شوے دے، هغه دلته نشته. وګورئ، دا هغه ځائ دے چرته چې يې هغه اېښودے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23753, 'Mark 16:7', 'Mark', 16, 7, '&nbsp;خو لاړې شئ، د هغۀ مريدانو او پطروس ته دا خبر ورسوئ چې هغه ستاسو نه وړاندې ګليل ته روان دے، تاسو به هغه هلته ووينئ لکه څنګه چې هغۀ تاسو ته فرمائيلى وُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23754, 'Mark 16:8', 'Mark', 16, 8, '&nbsp;نو هغوئ بهر ووتلې او د قبر نه په تېښته لاړې ځکه چې هغوئ يرې او ډېر هيبت اخستې وې. هغوئ هيچا ته هم غږ ونۀ کړو ځکه چې هغوئ يرېدلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23755, 'Mark 16:9', 'Mark', 16, 9, '&nbsp;کله چې عيسىٰ د اِتوار په سحر د مړو نه راژوندے شو نو اول مريم مګدلينى ته ښکاره شو د چا نه چې هغۀ اووۀ پيريان لرې کړى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23756, 'Mark 16:10', 'Mark', 16, 10, '&nbsp;هغه لاړه او د هغۀ مريدانو له ورغله چې ژړا انګولا يې کوله او هغوئ ته يې ټوله قيصه بيان کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23757, 'Mark 16:11', 'Mark', 16, 11, '&nbsp;خو چې هغوئ دا واورېدل چې هغه بيا ژوندے شوے دے او هغې ليدلے دے نو باور يې پرې ونۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23758, 'Mark 16:12', 'Mark', 16, 12, '&nbsp;پس له هغې نه هغه په يو بل شکل په دوو مريدانو راپېښ شو څوک چې بهر پټو ته په لاره روان وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23759, 'Mark 16:13', 'Mark', 16, 13, '&nbsp;هغوئ واپس لاړل او نورو مريدانو ته يې ووئيل خو هغوئ پرې يقين ونۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23760, 'Mark 16:14', 'Mark', 16, 14, '&nbsp;وروستو هغه يوولسو مريدانو ته هغه وخت ښکاره شو چې هغوئ روټۍ ته ناست وُو، او هغۀ هغوئ په خپلو بې‌يقينۍ او سختو زړونو ملامته کړل ځکه چې هغوئ د هغه خلقو په وينا يقين نۀ وو کړے چا چې هغه بيا ژوندے ليدلے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23761, 'Mark 16:15', 'Mark', 16, 15, '&nbsp;بيا هغۀ هغوئ ته وفرمائيل، ”ټولې دُنيا ته لاړ شئ او زما د زيرى وعظ ټول مخلوق ته وکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23762, 'Mark 16:16', 'Mark', 16, 16, '&nbsp;هر څوک چې پرې ايمان راوړى او بپتسمه واخلى نو هغه به خلاصون بيامومى، او هر څوک چې پرې ايمان رانۀ وړى هغه به مجرم شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23763, 'Mark 16:17', 'Mark', 16, 17, '&nbsp;څوک چې ايمان راوړى دا معجزې به ترېنه څرګنديږى چې زما په نوم به پيريان شړى او په نورو ژبو به خبرې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23764, 'Mark 16:18', 'Mark', 16, 18, '&nbsp;کۀ هغوئ مارانو له لاس وروړى يا زهر وخورى نو هغوئ ته به ضرر نۀ رسى، او په کومو بيمارانو چې هغوئ لاس کېږدى، هغوئ به روغ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23765, 'Mark 16:19', 'Mark', 16, 19, '&nbsp;هغوئ سره د خبرو کولو نه پس مالِک عيسىٰ آسمان ته پورته کړے شو او هغه د خُدائ پاک ښى طرف ته کښېناستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23766, 'Mark 16:20', 'Mark', 16, 20, '&nbsp;نو بيا هغوئ بهر ووتل او هر چرته يې کلام بيانولو، او مالِک د هغوئ سره کار کولو او د هغه معجزو په وسيله کومې چې هغۀ ښودلې کلام صحيح ثابتولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23767, 'Luke 1:1', 'Luke', 1, 1, '&nbsp;ډېرو خلقو په دې لاس پورې کړے دے چې د هغه واقعاتو ترتيب وار بيان وکړى کوم چې زمونږ په مينځ کښې تير شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23768, 'Luke 1:2', 'Luke', 1, 2, '&nbsp;بلکې هغوئ مونږ ته خبرې حواله کړې دى او چا چې دا واقعات د سر نه په خپلو سترګو ليدلى وُو هغوئ د زيرى خادِمان وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23769, 'Luke 1:3', 'Luke', 1, 3, '&nbsp;نو زۀ هم په خپل وار، اے خوږه تيوفيلوسه، ستا دپاره د پوره تحقيق نه پس دا ټولې خبرې په ترتيب سره ليکم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23770, 'Luke 1:4', 'Luke', 1, 4, '&nbsp;دا د دې دپاره چې ستا په هغه خبرو پوره يقين وشى د کومو نه چې تۀ خبر کړے شوے يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23771, 'Luke 1:5', 'Luke', 1, 5, '&nbsp;د يهوديه د هيروديس بادشاه په زمانه کښې يو يهودى اِمام وو چې نوم يې زکرياه وو. دے د ابياه د خاندانه وو. د هغۀ ښځه د هارون د اولاده وه. د هغې نوم اليشبع وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23772, 'Luke 1:6', 'Luke', 1, 6, '&nbsp;دوئ دواړه د خُدائ پاک په وړاندې رښتينى وُو او د مالِک خُدائ ټول حُکمونه او قانونونه يې بې‌عېبه منل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23773, 'Luke 1:7', 'Luke', 1, 7, '&nbsp;خو د هغوئ اولاد نۀ وو ځکه چې اليشبع شنډه وه او دوئ دواړه د ډېر عُمر وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23774, 'Luke 1:8', 'Luke', 1, 8, '&nbsp;يو ځلې چې د زکرياه د خاندان د خِدمت وار وو او هغۀ د اِمامت فرض پوره کولو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23775, 'Luke 1:9', 'Luke', 1, 9, '&nbsp;نو د اِمامت د طريقې په مطابق د هغۀ د نامى هسک راووتلو چې د مالِک خُدائ کور ته ننوځى او خوشبوئى وسيزى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23776, 'Luke 1:10', 'Luke', 1, 10, '&nbsp;دا د خوشبويۍ د سيزولو وخت وو او بهر ټوله جمع په عبادت کښې مشغوله وه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23777, 'Luke 1:11', 'Luke', 1, 11, '&nbsp;چې د مالِک خُدائ يوه فرښته د خوشبويۍ د قربان‌ګاه ښى طرف ته ولاړه ښکاره شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23778, 'Luke 1:12', 'Luke', 1, 12, '&nbsp;د دې په ليدلو زکرياه حېران شو او يرې واخستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23779, 'Luke 1:13', 'Luke', 1, 13, '&nbsp;خو فرښتې هغۀ ته وفرمائيل، ”زکرياه. يرېږه مه. ستا دُعا قبوله شوه، ستا د ښځې اليشبع به يو زوئ وشى او تۀ به د هغۀ نوم يحيىٰ کېږدې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23780, 'Luke 1:14', 'Luke', 1, 14, '&nbsp;ستا زړۀ به د خوشحالۍ نه ټوپونه وهى او ډېر خلق به د هغۀ په پېدايښت خوشحاله شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23781, 'Luke 1:15', 'Luke', 1, 15, '&nbsp;ځکه چې هغه به د مالِک خُدائ په نزد لوئ وى. هغه به مے او شراب کله هم نۀ څښى، د مور د ګېډې نه به هغه په روحُ القُدس معمور وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23782, 'Luke 1:16', 'Luke', 1, 16, '&nbsp;او هغه به ډېر بنى اِسرائيل د مالِک خُدائ پاک لارې ته راواړوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23783, 'Luke 1:17', 'Luke', 1, 17, '&nbsp;هغه به د الياس په روح او طاقت د مالِک نه وړاندې روان وى، چې د پلارانو په زړونو کښې خپلو بچو دپاره دوباره مينه واچوى او چې نافرمانه د صادقانو حکمت ته راوګرځوى او خلق د مالِک خُدائ د تابعدارۍ دپاره تيار کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23784, 'Luke 1:18', 'Luke', 1, 18, '&nbsp;زکرياه فرښتې ته وفرمائيل، ”زۀ څنګه په دې باور کولے شم؟ زۀ په خپله بوډا يم او زما ښځه هم بوډۍ ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23785, 'Luke 1:19', 'Luke', 1, 19, '&nbsp;فرښتې جواب ورکړو چې، ”زۀ جبرائيل يم، زۀ د خُدائ پاک په حضور کښې ودرېږم او زۀ يې تا سره د خبرو کولو او د دې زېرى درکولو دپاره رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23786, 'Luke 1:20', 'Luke', 1, 20, '&nbsp;خو اوس واوره چې تۀ به د خبرو طاقت بائيلې او د دې کار د کېدو پورې به ستا خولۀ بنده وى ځکه چې تا په ما باور ونۀ کړو، او په خپل مقرر وخت به زما خبره صحيح ثابته شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23787, 'Luke 1:21', 'Luke', 1, 21, '&nbsp;په دې دوران کښې خلق د زکرياه په اِنتظار وُو او سوچ يې کولو چې هغه د خُدائ په کور کښې ولې دومره ايسار شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23788, 'Luke 1:22', 'Luke', 1, 22, '&nbsp;کله چې هغه راووتو نو د هغوئ سره يې خبرې نۀ شوې کولے او هغوئ پوهه شُو چې هغۀ د خُدائ په کور کښې څۀ رويا وليده. او هغوئ ته يې اِشارې کولې خو ژبه يې نۀ چلېده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23789, 'Luke 1:23', 'Luke', 1, 23, '&nbsp;کله چې د هغۀ د خِدمت ورځې ختمې شوې نو زکرياه کور ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23790, 'Luke 1:24', 'Luke', 1, 24, '&nbsp;د دې نه پس د زکرياه ښځه اليشبع اُميدواره شوه او پينځۀ مياشتې هغې خپل ځان پټ وساتلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23791, 'Luke 1:25', 'Luke', 1, 25, '&nbsp;دا يې ووئيل چې، ”دا د مالِک خُدائ رضا ده چې اوس هغۀ زما سترګې اوچتې کړې او زۀ يې د بنى آدمو په وړاندې په خپل فضل سره د سپکاوى نه بچ کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23792, 'Luke 1:26', 'Luke', 1, 26, '&nbsp;بيا د هغې په شپږمه مياشت خُدائ پاک جبرائيل فرښته د ګليل ناصرت نومې ښار ته يوې پېغلې ته ورولېږله', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23793, 'Luke 1:27', 'Luke', 1, 27, '&nbsp;چې کوژدن يې د داؤد د خاندان يوسف نومې سړى سره شوې وه او د دې پېغلې نوم مريم وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
