(23795, 'Luke 1:29', 'Luke', 1, 29, '&nbsp;هغې چې څۀ وفرمائيل مريم په هغې ډېره فکرمنده شوه او حېرانه وه چې د دې مبارکۍ څۀ مطلب دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23796, 'Luke 1:30', 'Luke', 1, 30, '&nbsp;بيا فرښتې هغې ته وفرمائيل چې، ”مريمې. يرېږه مه. خُدائ پاک په تا مهربانه شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23797, 'Luke 1:31', 'Luke', 1, 31, '&nbsp;ګوره، تۀ به اُميدواره شې او يو زوئ به دې وشى او تۀ به د هغۀ نوم عيسىٰ کېږدې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23798, 'Luke 1:32', 'Luke', 1, 32, '&nbsp;هغه به لوئ وى او هغه به د خُدائ تعالىٰ زوئ وبللے شى. مالِک خُدائ پاک به هغۀ ته د خپل نيکۀ داؤد تخت ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23799, 'Luke 1:33', 'Luke', 1, 33, '&nbsp;هغه به د تل دپاره د يعقوب په خاندان بادشاهى کوى او بادشاهى به يې هيڅکله نۀ ختميږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23800, 'Luke 1:34', 'Luke', 1, 34, '&nbsp;مريمې وفرمائيل چې، ”دا څنګه کېدے شى؟ زۀ خو لا وادۀ شوې هم نۀ يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');